import re
from urllib.parse import urlparse

def domains(text):
    urls = re.findall(r"https?://[^\s\"<>)]+", text)
    return sorted({urlparse(u).hostname for u in urls})

def ips(text):
    return sorted(set(re.findall(r"\b\d{1,3}(?:\.\d{1,3}){3}\b", text)))

with open("mail.txt", encoding="utf-8") as f:
    text = f.read()
print("DOMAINS", domains(text))
print("IPS", ips(text))
